function phase6Race(array $requests): array {
	global $environment,$phase5Process; $writers=[];
	foreach($requests as $request) { $writer=proc_open([PHP_BINARY,__DIR__.'/resources-writer.php'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w']],$pipes,dirname(__DIR__),$environment); fwrite($pipes[0],json_encode(['actor'=>1,'process'=>$phase5Process,...$request],JSON_THROW_ON_ERROR)); fclose($pipes[0]); $writers[]=[$writer,$pipes]; }
	$results=[]; foreach($writers as [$writer,$pipes]) { $out=stream_get_contents($pipes[1]); $err=stream_get_contents($pipes[2]); fclose($pipes[1]); fclose($pipes[2]); verify(proc_close($writer)===0,'Escritor concurrente finaliza sin error técnico: '.$err); $results[]=json_decode($out,true,512,JSON_THROW_ON_ERROR); } return $results;
}
function phase6Statuses(array $rows,array $expected,string $description): void { $actual=array_column($rows,'status'); sort($actual); sort($expected); verify($actual===$expected,$description.': '.json_encode($actual)); }
